<?php
require_once __DIR__.'/../includes/functions.php';require_admin();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=alan-orders.csv');$out=fopen('php://output','w');fputcsv($out,['Order','Customer','Phone','Wilaya','Delivery','Shipping','Total','Status','Date']);foreach(db()->query('SELECT o.order_number,o.full_name,o.phone,w.name wilaya,o.delivery_type,o.shipping_cost,o.total,o.status,o.created_at FROM orders o LEFT JOIN wilayas w ON w.id=o.wilaya_id ORDER BY o.id DESC') as $o)fputcsv($out,$o);fclose($out);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'update';if($action==='delete'){db()->prepare('DELETE FROM orders WHERE id=?')->execute([$id]);flash('success','Order deleted.');}else{$status=$_POST['status'];$note=trim($_POST['admin_notes']??'');db()->prepare('UPDATE orders SET status=?,admin_notes=?,fraud_status=? WHERE id=?')->execute([$status,$note,$_POST['fraud_status']??'clear',$id]);db()->prepare('INSERT INTO order_timeline(order_id,status,admin_note) VALUES(?,?,?)')->execute([$id,$status,$note]);flash('success','Order updated.');}header('Location: '.base('admin/orders.php'.(!empty($_POST['return'])?'?view='.$id:'')));exit;}
$view=(int)($_GET['view']??0);if($view){$st=db()->prepare('SELECT o.*,w.name wilaya,c.name commune FROM orders o LEFT JOIN wilayas w ON w.id=o.wilaya_id LEFT JOIN communes c ON c.id=o.commune_id WHERE o.id=?');$st->execute([$view]);$order=$st->fetch();$items=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$view]);$timeline=db()->prepare('SELECT * FROM order_timeline WHERE order_id=? ORDER BY id DESC');$timeline->execute([$view]);$adminTitle='Order '.$order['order_number'];include 'header.php';?>
<div class="panel"><div class="panel-head"><h2><?=e($order['full_name'])?> · <?=e($order['order_number'])?></h2><div><?php $waMsg = urlencode("مرحباً ". $order['full_name'] ."،\nأود تأكيد طلبك رقم " . $order['order_number'] . " من متجر ALAN.\nالإجمالي: " . number_format($order['total'], 2) . " د.ج\nهل ترغب(ين) في تأكيد الطلب لشحنه؟"); $waPhone = '213' . ltrim($order['phone'], '0'); ?><a class="button" style="background:#25D366; color:#fff; border:none;" target="_blank" href="https://wa.me/<?=e($waPhone)?>?text=<?=$waMsg?>">تأكيد عبر واتساب</a> <a class="button ghost" href="<?=base('admin/orders.php')?>">Back</a></div></div><div class="cards"><div class="stat"><span>Total</span><b><?=money($order['total'])?></b></div><div class="stat"><span>Shipping</span><b><?=money($order['shipping_cost'])?></b></div><?php if(!empty($order['promo_code'])): ?><div class="stat"><span>Promo Code</span><b style="color:var(--brand);"><?=e($order['promo_code'])?> (-<?=money($order['discount_amount'])?>)</b></div><?php endif; ?><div class="stat"><span>Risk</span><b><?=$order['risk_score']?></b></div><div class="stat"><span>Placed</span><b><?=e(date('d M',strtotime($order['created_at'])))?></b></div></div><div class="panel"><h2>Delivery & customer</h2><p><?=e($order['phone'])?> · <?=e($order['phone2'])?><br><?=e($order['wilaya'])?>, <?=e($order['commune'])?> — <?=e($order['address'])?><br><small><?=e($order['ip_address'])?> · <?=e($order['user_agent'])?></small></p></div><div class="panel"><h2>Items</h2><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?><?php if(!empty($i['color'])||!empty($i['size'])):?><br><small style="color:var(--text)"><?=e($i['color']??'')?> <?=!empty($i['color'])&&!empty($i['size'])?'·':''?> <?=e($i['size']??'')?></small><?php endif;?></td><td><?=$i['quantity']?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['total'])?></td></tr><?php endforeach;?></table></div></div><form class="form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$view?>"><input type="hidden" name="return" value="1"><div><label>Status</label><select name="status"><?php foreach(['received','confirmed','preparing','shipped','out_for_delivery','delivered','cancelled','rejected'] as $s):?><option <?=$order['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div><label>Fraud decision</label><select name="fraud_status"><?php foreach(['clear','review','blocked'] as $s):?><option <?=$order['fraud_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="full"><label>Admin note</label><textarea name="admin_notes"><?=e($order['admin_notes'])?></textarea></div><button class="button gold">Save timeline update</button></form><div class="panel"><h2>Timeline</h2><?php foreach($timeline as $t):?><p><span class="tag"><?=e($t['status'])?></span> <?=e($t['admin_note'])?> <small class="muted"><?=e($t['created_at'])?></small></p><?php endforeach;?></div></div><?php include 'footer.php';exit;}
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$sql='SELECT o.*,w.name wilaya FROM orders o LEFT JOIN wilayas w ON w.id=o.wilaya_id WHERE 1';$args=[];if($q!==''){$sql.=' AND (o.order_number LIKE ? OR o.full_name LIKE ? OR o.phone LIKE ?)';$args=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];}if($status!==''){$sql.=' AND o.status=?';$args[]=$status;}$sql.=' ORDER BY o.id DESC LIMIT 200';$st=db()->prepare($sql);$st->execute($args);$orders=$st->fetchAll();$adminTitle='Orders';include 'header.php';?>
<div class="panel"><div class="panel-head"><h2>Order operations</h2><form class="table-tools"><input class="search-input" name="q" value="<?=e($q)?>" placeholder="Order, customer or phone"><select name="status"><option value="">All statuses</option><?php foreach(['received','confirmed','preparing','shipped','out_for_delivery','delivered','cancelled','rejected'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="button">Filter</button></form></div><?php if(!$orders):?><div class="empty">No orders found.</div><?php else:?><div class="table-wrap"><table class="table"><tr><th>Order</th><th>Customer</th><th>Delivery</th><th>Total</th><th>Status</th><th>Risk</th><th></th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['full_name'])?><br><?=e($o['phone'])?></td><td><?=e($o['wilaya'])?><br><small><?=e($o['delivery_type']??'—')?></small></td><td><?=money($o['total'])?></td><td><span class="tag status-<?=e($o['status'])?>"><?=e($o['status'])?></span></td><td><?=$o['risk_score']?> · <?=e($o['fraud_status'])?></td><td><a class="button" href="?view=<?=$o['id']?>">View</a></td></tr><?php endforeach;?></table></div><?php endif;?></div><?php include 'footer.php'; ?>
